:root { --right-sidebar-cover-art-size: 85px; } 
.main-nowPlayingView-coverArt { width: var(--right-sidebar-cover-art-size); } 
.main-nowPlayingView-coverArtContainer { min-height: unset !important; width: var(--right-sidebar-cover-art-size) !important; } 
.main-nowPlayingView-nowPlayingGrid { flex-direction: row !important;  align-items: center; } 
.main-nowPlayingView-contextItemInfo { flex: 1; } 
.main-nowPlayingView-contextItemInfo .main-trackInfo-name { font-size: 1.25rem; } 
.main-nowPlayingView-contextItemInfo .main-trackInfo-artists { font-size: 0.85rem; } 
.main-nowPlayingView-contextItemInfo:before { display: none !important; }
